def word_frequency(text):
    counts = {}
    for word in text.lower().split():
        counts[word] = counts.get(word, 0) + 1
    return counts

def group_by_first_letter(words):
    groups = {}
    for word in words:
        letter = word[0].lower()
        if letter not in groups:
            groups[letter] = []
        groups[letter].append(word)
    for letter in groups:
        groups[letter] = sorted(groups[letter])
    return groups

def compter_mots_par_longueur(texte):
    mots = texte.split()
    result = {}
    for mot in mots:
        longueur = len(mot)
        result[longueur] = result.get(longueur, 0) + 1
    return result

def caesar_shift(text, shift):
    result = ""
    for char in text:
        if "a" <= char <= "z":
            result += chr((ord(char) - ord("a") + shift) % 26 + ord("a"))
        elif "A" <= char <= "Z":
            result += chr((ord(char) - ord("A") + shift) % 26 + ord("A"))
        else:
            result += char
    return result

def to_int_list(tokens):
    values = []
    errors = 0
    for token in tokens:
        try:
            values.append(int(token))
        except ValueError:
            errors += 1
    return {"values": values, "errors": errors}

from datetime import date


def days_until(today, deadline):
    try:
        start = date.fromisoformat(today)
        end = date.fromisoformat(deadline)
    except ValueError:
        return None
    if end < start:
        return 0
    return (end - start).days

def flatten(nested):
    result = []
    for item in nested:
        if isinstance(item, list):
            result += flatten(item)
        else:
            result.append(item)
    return result

class Parking:
    def __init__(self, capacity):
        self.capacity = capacity
        self.cars = []

    def free_spots(self):
        return self.capacity - len(self.cars)

    def enter(self, plate):
        if self.free_spots() == 0 or plate in self.cars:
            return False
        self.cars.append(plate)
        return True

    def leave(self, plate):
        if plate not in self.cars:
            return False
        self.cars.remove(plate)
        return True

class CompteBancaire:
    def __init__(self, solde=0):
        self.solde = solde

    def deposer(self, montant):
        if montant <= 0:
            return False
        self.solde += montant
        return True

    def retirer(self, montant):
        if montant <= 0 or montant > self.solde:
            return False
        self.solde -= montant
        return True

class Panier:
    def __init__(self):
        self.articles = {}

    def ajouter(self, nom, prix, quantite=1):
        if quantite <= 0 or prix < 0:
            return False
        if nom in self.articles:
            self.articles[nom]["quantite"] += quantite
        else:
            self.articles[nom] = {"prix": prix, "quantite": quantite}
        return True

    def retirer(self, nom):
        return self.articles.pop(nom, None) is not None

    def total(self):
        somme = 0
        for article in self.articles.values():
            somme += article["prix"] * article["quantite"]
        return somme

class CompteurBorne:
    def __init__(self, minimum=0, maximum=10):
        self.minimum = minimum
        self.maximum = maximum
        self.valeur = minimum

    def incrementer(self, pas=1):
        self.valeur = min(self.valeur + pas, self.maximum)
        return self.valeur

    def decrementer(self, pas=1):
        self.valeur = max(self.valeur - pas, self.minimum)
        return self.valeur

    def reinitialiser(self):
        self.valeur = self.minimum

class Pile:
    def __init__(self, capacite=3):
        self.capacite = capacite
        self.elements = []

    def empiler(self, element):
        if len(self.elements) >= self.capacite:
            return False
        self.elements.append(element)
        return True

    def depiler(self):
        if not self.elements:
            return None
        return self.elements.pop()

    def sommet(self):
        if not self.elements:
            return None
        return self.elements[-1]

    def taille(self):
        return len(self.elements)

