class Manager(Employe):
    def __init__(self, nom, salaire_base, prime=100):
        super().__init__(nom, salaire_base)
        self.prime = prime
        self.equipe = []

    def ajouter_membre(self, nom):
        if nom in self.equipe:
            return False
        self.equipe.append(nom)
        return True

    def salaire(self):
        return super().salaire() + self.prime * len(self.equipe)

