class Inventaire:
    def __init__(self):
        self.stock = {}

    def ajouter(self, nom, quantite=1):
        if quantite <= 0:
            return False
        self.stock[nom] = self.stock.get(nom, 0) + quantite
        return True

    def retirer(self, nom, quantite=1):
        if quantite <= 0 or self.stock.get(nom, 0) < quantite:
            return False
        self.stock[nom] -= quantite
        if self.stock[nom] == 0:
            del self.stock[nom]
        return True

    def __len__(self):
        return len(self.stock)

    def __contains__(self, nom):
        return nom in self.stock

    def __str__(self):
        parties = []
        for nom in sorted(self.stock):
            parties.append(f"{nom}:{self.stock[nom]}")
        return ", ".join(parties)

class Gradebook:
    def __init__(self):
        self.grades = {}

    def add_grade(self, name, grade):
        if name not in self.grades:
            self.grades[name] = []
        self.grades[name].append(grade)

    def average(self, name):
        if name not in self.grades:
            return None
        values = self.grades[name]
        return round(sum(values) / len(values), 2)

    def averages(self):
        return {name: self.average(name) for name in self.grades}

    def above(self, threshold):
        return sorted([name for name, avg in self.averages().items() if avg >= threshold])

class NumberBag:
    def __init__(self, values):
        self.values = list(values)

    @staticmethod
    def is_even(n):
        return n % 2 == 0

    def _select(self, predicate):
        for value in self.values:
            if predicate(value):
                yield value

    def evens(self):
        return list(self._select(NumberBag.is_even))

    def odds(self):
        return list(self._select(lambda v: not NumberBag.is_even(v)))

    def top(self, k):
        return sorted(self.values, key=lambda v: -v)[:k]

    def add(self, value):
        self.values.append(value)
